-- sys_role_route: 角色可访问的路由（按 route id 授权）

CREATE TABLE IF NOT EXISTS sys_role_route (
  id VARCHAR(128) PRIMARY KEY,
  role_id VARCHAR(64) NOT NULL,
  route_id VARCHAR(64) NOT NULL,
  create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  update_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted INT NOT NULL DEFAULT 0
);

COMMENT ON TABLE sys_role_route IS '角色-路由授权';
CREATE INDEX IF NOT EXISTS idx_sys_role_route_role ON sys_role_route(role_id) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_sys_role_route_route ON sys_role_route(route_id) WHERE deleted = 0;
CREATE UNIQUE INDEX IF NOT EXISTS uk_sys_role_route_pair ON sys_role_route(role_id, route_id) WHERE deleted = 0;

